function validate([nums, k]) {
  if (nums.length < 1 || nums.length > 1000) return 'nums needs 1 to 1000 values.';
  if (nums.some(v => !Number.isInteger(v) || v < 1 || v > 1000)) return 'Each value of nums is an integer from 1 to 1000.';
  if (!Number.isInteger(k) || k < 1 || k > 100) return 'k is an integer from 1 to 100.';
  return null;
}

