brute:
function minOperations(nums, k) {
  // Really perform the operations on a copy, always on the largest element, and re-add the array after each one.
  const values = [...nums];
  const total = () => values.reduce((a, b) => a + b, 0);
  let operations = 0;
  while (total() % k !== 0) {
    let largest = 0;
    for (let i = 1; i < values.length; i++) if (values[i] > values[largest]) largest = i;
    values[largest]--;
    operations++;
  }
  return operations;
}

