function generate(rand, size) {
  const int = (lo, hi) => lo + Math.floor(rand() * (hi - lo + 1));
  if (size === 'large') {
    const n = int(900, 1000);
    return [Array.from({ length: n }, () => int(1, 1000)), int(1, 100)];
  }
  const n = int(1, 8);
  const top = rand() < 0.5 ? 10 : 1000;
  const k = rand() < 0.1 ? 1 : int(1, rand() < 0.5 ? 12 : 100);
  return [Array.from({ length: n }, () => int(1, top)), k];
}
